// Metadata-only difference classification. No assembly is loaded or written.
using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Collections.Generic;
using Mono.Cecil;
using RR23.MetadataRestoration;

static class TypeContractInventory
{
 static IEnumerable<TypeDefinition> Walk(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var n in Walk(t.NestedTypes))yield return n;}}
 static string[] Attrs(ICustomAttributeProvider p)=>p.CustomAttributes.Where(a=>a.AttributeType.Namespace!="Cpp2IlInjected").Select(a=>CanonicalMetadataSignatures.Type(a.Constructor.DeclaringType)+"::"+CanonicalMetadataSignatures.Method(a.Constructor)+":"+Convert.ToHexString(a.GetBlob())).OrderBy(s=>s).ToArray();
 static object Header(TypeDefinition t)=>new{flags=(uint)t.Attributes,flags_text=t.Attributes.ToString(),packing=t.PackingSize,class_size=t.ClassSize,before_field_init=t.IsBeforeFieldInit,has_static_constructor=t.Methods.Any(m=>m.IsConstructor&&m.IsStatic),is_interface=t.IsInterface,is_value_type=t.IsValueType};
 static void Need(bool b,string s){if(!b)throw new InvalidDataException(s);}
 static object? Generic(IGenericParameterProvider a,IGenericParameterProvider o,IGenericParameterProvider? initial,Func<TypeReference,string> forward,string owner)
 {
  if(a.GenericParameters.Count!=o.GenericParameters.Count)return new{owner,arity_mismatch=true,compiled=a.GenericParameters.Count,original=o.GenericParameters.Count};var differences=new List<object>();
  for(int i=0;i<a.GenericParameters.Count;i++){var ca=a.GenericParameters[i];var ro=o.GenericParameters[i];var cc=ca.Constraints.Select(c=>CanonicalMetadataSignatures.Type(c.ConstraintType)).OrderBy(s=>s).ToArray();var rc=ro.Constraints.Select(c=>ProjectedCanonicalSignatures.Type(c.ConstraintType,forward)).OrderBy(s=>s).ToArray();var ac=Attrs(ca);var oc=Attrs(ro);var ic=initial!=null&&initial.GenericParameters.Count==o.GenericParameters.Count?Attrs(initial.GenericParameters[i]):null;
   if(ca.Attributes!=ro.Attributes||ca.Position!=ro.Position||ca.Type!=ro.Type||!cc.SequenceEqual(rc)||!ac.SequenceEqual(oc)||ic!=null&&!ic.SequenceEqual(oc))differences.Add(new{position=i,compiled_flags=(uint)ca.Attributes,original_flags=(uint)ro.Attributes,compiled_position=ca.Position,original_position=ro.Position,compiled_owner_kind=ca.Type.ToString(),original_owner_kind=ro.Type.ToString(),compiled_constraints=cc,projected_original_constraints=rc,compiled_attributes=ac,raw_modern_attributes=oc,initial_provider_attributes=ic,flags_equal=ca.Attributes==ro.Attributes,position_and_owner_kind_equal=ca.Position==ro.Position&&ca.Type==ro.Type,constraints_equal=cc.SequenceEqual(rc),attributes_equal_to_modern=ac.SequenceEqual(oc),attributes_equal_to_initial=ic!=null&&ac.SequenceEqual(ic),raw_provider_attribute_agreement=ic!=null&&oc.SequenceEqual(ic)});
  }
  return differences.Count==0?null:new{owner,parameters=differences};
 }
 public static int Main(string[] args)
 {
  var opt=new Dictionary<string,string>();for(int i=0;i<args.Length;i+=2)opt.Add(args[i],args[i+1]);using var input=JsonDocument.Parse(File.ReadAllBytes(opt["--input"]));var root=input.RootElement;using var compiled=AssemblyDefinition.ReadAssembly(root.GetProperty("compiled").GetString(),new ReaderParameters{ReadingMode=ReadingMode.Deferred});using var raw=AssemblyDefinition.ReadAssembly(root.GetProperty("raw").GetString(),new ReaderParameters{ReadingMode=ReadingMode.Deferred});using var initial=AssemblyDefinition.ReadAssembly(root.GetProperty("initial").GetString(),new ReaderParameters{ReadingMode=ReadingMode.Deferred});var cd=Walk(compiled.MainModule.Types).ToDictionary(t=>t.FullName);var rd=Walk(raw.MainModule.Types).ToDictionary(t=>t.FullName);var id=Walk(initial.MainModule.Types).ToDictionary(t=>t.FullName);var aliases=new Dictionary<string,string>();foreach(var row in root.GetProperty("aliases").EnumerateArray()){var key=row.GetProperty("assembly").GetString()+":"+row.GetProperty("original").GetString();var value=row.GetProperty("compiled").GetString()!;if(aliases.TryGetValue(key,out var old))Need(old==value,"Conflicting alias identity");else aliases.Add(key,value);}Func<TypeReference,string> forward=t=>aliases.TryGetValue(CanonicalMetadataSignatures.Assembly(t)+":"+t.FullName,out var x)?x:t.FullName;
  var rows=new List<object>();var methodRows=new List<object>();var unmatched=new List<object>();int count=0,flags=0,layout=0,bases=0,interfaces=0,generics=0,methodGenericCount=0;using var headers=new StreamWriter(opt["--headers"],false);
  foreach(var row in root.GetProperty("types").EnumerateArray()){var name=row.GetProperty("original_full_name").GetString()!;var cname=row.GetProperty("compiled_full_name").GetString()!;Need(rd.TryGetValue(name,out var o)&&cd.TryGetValue(cname,out var a),"Source type inventory absent from exact raw/compiled modules: "+name);var rt=rd[name];var ct=cd[cname];id.TryGetValue(name,out var it);headers.WriteLine(JsonSerializer.Serialize(new{original=name,compiled=cname,raw_flags=(uint)rt.Attributes,raw_packing=rt.PackingSize,raw_class_size=rt.ClassSize}));count++;
   var bf=(ct.BaseType==null?null:CanonicalMetadataSignatures.Type(ct.BaseType));var bo=(rt.BaseType==null?null:ProjectedCanonicalSignatures.Type(rt.BaseType,forward));var ci=ct.Interfaces.Select(x=>CanonicalMetadataSignatures.Type(x.InterfaceType)).OrderBy(x=>x).ToArray();var ri=rt.Interfaces.Select(x=>ProjectedCanonicalSignatures.Type(x.InterfaceType,forward)).OrderBy(x=>x).ToArray();var gp=Generic(ct,rt,it,forward,name);bool fd=ct.Attributes!=rt.Attributes,ld=ct.PackingSize!=rt.PackingSize||ct.ClassSize!=rt.ClassSize,bd=bf!=bo,inf=!ci.SequenceEqual(ri);if(fd)flags++;if(ld)layout++;if(bd)bases++;if(inf)interfaces++;if(gp!=null)generics++;
   if(fd||ld||bd||inf||gp!=null)rows.Add(new{original=name,compiled=cname,source_path=row.GetProperty("source_path").GetString(),original_header=Header(rt),actual_header=Header(ct),flag_xor=(uint)(ct.Attributes^rt.Attributes),flags_differ=fd,layout_differs=ld,base_differs=bd,interfaces_differ=inf,compiled_base=bf,projected_original_base=bo,compiled_interfaces=ci,projected_original_interfaces=ri,generic_parameters=gp});
   foreach(var rm in rt.Methods.Where(m=>m.HasGenericParameters)){var expected=ProjectedCanonicalSignatures.Method(rm,forward);var matches=ct.Methods.Where(m=>CanonicalMetadataSignatures.Method(m)==expected).ToArray();if(matches.Length!=1){unmatched.Add(new{owner=name,original_method=rm.FullName,projected_canonical_signature=expected,compiled_matches=matches.Length});continue;}methodGenericCount++;var candidates=it?.Methods.Where(m=>m.Name==rm.Name&&m.GenericParameters.Count==rm.GenericParameters.Count&&m.Parameters.Count==rm.Parameters.Count).ToArray();var im=candidates?.Length==1?candidates[0]:null;var diff=Generic(matches[0],rm,im,forward,rm.FullName);if(diff!=null)methodRows.Add(diff);}
  }
  using var output=File.Create(opt["--output"]);JsonSerializer.Serialize(output,new{schema="current-core-original-type-contract-differences/v1",types_compared=count,type_flag_differences=flags,class_layout_differences=layout,base_type_differences=bases,interface_differences=interfaces,type_generic_parameter_differences=generics,unique_generic_methods_compared=methodGenericCount,generic_method_differences=methodRows.Count,unmatched_generic_method_count=unmatched.Count,type_differences=rows,generic_method_changes=methodRows,unmatched_generic_methods=unmatched,raw_modern_custom_attribute_completeness_not_assumed=true,compiled_missing_original_method_policy_not_relaxed=true,project_modified=false,game_code_executed=false},new JsonSerializerOptions{WriteIndented=true});return 0;
 }
}
